    "pinyin": "zǒng zhī gòu wù wǎng zhàn dài gòu wǎng zhàn jí pāi mài wǎng zhàn gè yǒu gè de tè sè",
    "vi": "Tóm lại, trang mua sắm, trang mua hộ và trang đấu giá đều có đặc điểm riêng."
